fn update(self:&mut LineGankerPlan, _version, _rnd, player, data, goal_data, _positioning_score, _debug)

// --- ganker.rs:43 ---
team = player.info.team              // usize, 2 미만이 아니면 panic_bounds_check
pos  = player.info.position.as_index()   // 0..4
champ = data.cache.player_champion[team][pos].unwrap()   // None 이면 unwrap 패닉

// --- ganker.rs:44,47 ---
max_hp = champ.stat_cached.hp        // 0 이면 div-by-zero 패닉
hp_ratio = champ.hp * 100 / max_hp
if hp_ratio < 41 {                                   // :47
    self.chats.push(Chat::Cancel(CancelReason::LowHpSelf))   // :48  (태그17, 페이로드0)
    self.phase = LineGankerPhase::Cancel                     // 값 8
    return
}

// --- ganker.rs:54 : bush = self.target_bush_v30(...) (전량 인라인, 원본 :248~:305) ---
line = self.line                       // LineType 0=Top 1=Mid 2=Bottom
tower = cache.tower(line, team)        // :249 — (0x180 + line*32)[team] .or( (0x190 + line*32)[team] )
                                       //        = *_tower[team] 이 null 이면 *_tower2[team]

if tower.is_none() {                   // :250 — 그 라인 타워가 둘 다 사라진 상태
    bush = match line {
        Top    => if team==0 {2} else {16},   // :252
        Mid    => if team==0 {4} else {17},   // :253
        Bottom => if team==0 {9} else {21},   // :254
    }
} else {                               // :258~ tower 존재
    match line {
    // ---- Top (:263) ----
    Top => {
        let Tower(info) = tower.ty else { unreachable!() }   // ty!=2 → panic "internal error: entered unreachable code" (:274)
        if tower.ty.is_tower2() {                            // :264  (Tower.ty > 4)
            bush = if team==0 {3} else {6}                   // :265
        } else if info.nearest_enemy.is_some() {             // :267  (Entity+0x88 태그 != 0)
            bush = if team==0 {6} else {3}                   // :268  ★좌우 반전
        } else {
            bush = if team==0 {3} else {6}                   // :270
        }
    }
    // ---- Mid (:278) ---- ※ Top/Bottom 과 달리 ty!=Tower 여도 패닉하지 않고 :285 로 간다
    Mid => {
        if tower.ty.is_tower2() {                            // :278
            if is_top_side(context, champ.x, champ.y) {      // :279
                bush = if team==0 {13} else {18}             // :282
            } else {
                bush = if team==0 {8} else {12}              // :280
            }
        } else {
            bush = if is_top_side(context, champ.x, champ.y) {14} else {11}   // :285  ★team 무관
        }
    }
    // ---- Bottom (:293) ----
    Bottom => {
        let Tower(info) = tower.ty else { unreachable!() }   // ty!=2 → panic (:304)
        if tower.ty.is_tower2() {                            // :294
            bush = if team==0 {15} else {20}                 // :295
        } else if info.nearest_enemy.is_some() {             // :297
            bush = if team==0 {20} else {15}                 // :298  ★좌우 반전
        } else {
            bush = if team==0 {15} else {20}                 // :300
        }
    }
    }
}
// is_top_side(ctx,x,y) (game_core map_regions.rs:21~24, 인라인)
//   = { let ry = ctx.setting.height - y; ry < x }

// --- ganker.rs:55 ---
gx = min(champ.x / 32000, 29)
gy = min(champ.y / 32000, 29)
champ_bush = context.map.bushes[gy][gx]        // MapDef+0x1c98, [[usize;30];30]

// --- ganker.rs:56 ---
if champ_bush != bush { return }                // 아직 목표 수풀에 도착 안 함 → 아무것도 안 함

// --- ganker.rs:57 ---
if goal_data.has_near_line_enemy(line, context.map) { return }   // 갱크 대상이 아직 라인 근처에 있음 → 유지

// --- ganker.rs:58 ---
self.chats.push(Chat::Cancel(CancelReason::TargetMissing))
self.phase = LineGankerPhase::Cancel            // 값 8
